def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbors(row, col):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        neighbors = []
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col):
                neighbors.append((new_row, new_col))
        return neighbors

    def backtrack(path, visited):
        current_row, current_col = path[-1]
        if (current_row, current_col) == goal:
            return path[:]
        for neighbor in get_neighbors(current_row, current_col):
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                if backtrack(path, visited):
                    return path
                path.pop()
                visited.remove(neighbor)
        return []

    visited = set()
    visited.add(start)
    path = [start]
    result = backtrack(path, visited)
    return result if result else []
