def solve(grid, start, goal):
    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def modified_warnsdorff(r, c, path):
        if (r, c) == goal:
            return path + [(r, c)]

        neighbors = get_neighbors(r, c)
        if not neighbors:
            return None

        # Modified Warnsdorff's Rule: prefer the neighbor with the fewest onward moves
        neighbor_scores = []
        for nr, nc in neighbors:
            score = len(get_neighbors(nr, nc))
            neighbor_scores.append((score, nr, nc))

        # Sort by number of moves, then by row (to break ties)
        neighbor_scores.sort()
        for score, nr, nc in neighbor_scores:
            # Avoid revisiting the parent node
            if (nr, nc) != path[-2] if len(path) > 1 else True:
                new_path = path + [(nr, nc)]
                result = modified_warnsdorff(nr, nc, new_path)
                if result:
                    return result

        return None

    # Check if start or goal is invalid
    if not is_valid(*start) or not is_valid(*goal):
        return []

    # Start the search
    path = [start]
    result = modified_warnsdorff(start[0], start[1], path)
    return result if result else []
