def solve(grid, start, goal):
    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def hill_climb(start, goal):
        path = [start]
        current = start
        while True:
            if current == goal:
                return path
            neighbors = get_neighbors(current[0], current[1])
            if not neighbors:
                return []
            # Find the neighbor with the highest "desirability"
            # Here, "desirability" is defined as how close the neighbor is to the goal
            best = None
            best_dist = float('inf')
            for neighbor in neighbors:
                dist = abs(neighbor[0] - goal[0]) + abs(neighbor[1] - goal[1])
                if dist < best_dist:
                    best_dist = dist
                    best = neighbor
            if best not in path:
                path.append(best)
                current = best
            else:
                return []

    return hill_climb(start, goal)
