                break
            path.append(best)
            current = best
            if current == goal:
                return path
        return []

    # Try hill climbing from start
    path = hill_climb()
    if path and path[-1] == goal:
        return path

    # If Hill Climbing failed, use BFS to find a path
    def bfs():
        visited = [[False for _ in range(cols)] for _ in range(rows)]
        queue = deque([(start, [start])])
        visited[start[0]][start[1]] = True

