def solve(grid, start, goal):
    from collections import defaultdict

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    # Convert grid to a graph representation: adjacency list
    def build_graph():
        graph = defaultdict(list)
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '.':
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                            graph[(r, c)].append((nr, nc))
        return graph

    graph = build_graph()
    if start not in graph or goal not in graph:
        return []

    # Hierholzer's Algorithm to find an Eulerian path
    def hierholzer(start):
        stack = [start]
        path = []
        while stack:
            current = stack[-1]
            if graph[current]:
                next_node = graph[current].pop()
                stack.append(next_node)
            else:
                path.append(stack.pop())
        return path[::-1]

    # Find an Eulerian path from start to goal
    # First, check if the path exists (degree check)
    def is_eulerian_path(start, goal):
        degrees = defaultdict(int)
        for node in graph:
            degrees[node] = len(graph[node])
        for node in degrees:
            if node == start:
                degrees[node] -= 1
            elif node == goal:
                degrees[node] -= 1
            if degrees[node] % 2 != 0:
                return False
        return True

    if is_eulerian_path(start, goal):
        path = hierholzer(start)
        # Extract the path from start to goal
        path = path[:path.index(goal)+1]
        return path
    else:
        return []

