from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    # Helper function to check feasibility of a path length 'max_len'
    def is_feasible(max_len):
        # BFS to find shortest path length
        visited = [[False] * cols for _ in range(rows)]
        q = deque()
        q.append((start[0], start[1], 0))  # (row, col, steps)
        visited[start[0]][start[1]] = True

        while q:
            r, c, steps = q.popleft()
            if (r, c) == goal:
                return True
            if steps >= max_len:
                continue
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and not visited[nr][nc]:
                    visited[nr][nc] = True
                    q.append((nr, nc, steps + 1))
        return False

    # Binary search on possible path lengths
    min_len = 1
    max_len = rows * cols  # maximum possible path length (in a grid)
    answer = []

    # Find the minimal path length using binary search
    while min_len <= max_len:
        mid = (min_len + max_len) // 2
        if is_feasible(mid):
            max_len = mid - 1
        else:
            min_len = mid + 1

    # Now find the actual path with the determined minimal length
    def find_path():
        visited = [[False] * cols for _ in range(rows)]
        q = deque()
        q.append((start[0], start[1], 0, [(start[0], start[1])]))  # (row, col, steps, path)
        visited[start[0]][start[1]] = True

        while q:
            r, c, steps, path = q.popleft()
            if (r, c) == goal:
                return path
            if steps >= min_len:
                continue
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and not visited[nr][nc]:
                    visited[nr][nc] = True
                    new_path = path + [(nr, nc)]
                    q.append((nr, nc, steps + 1, new_path))
        return []

    return find_path()
