from collections import deque

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    # Bidirectional BFS
    # Initialize queues for forward and backward search
    forward_queue = deque([(start, [start])])
    forward_visited = set([start])
    backward_queue = deque([(goal, [goal])])
    backward_visited = set([goal])

    while forward_queue and backward_queue:
        # Expand forward direction
        if forward_queue:
            current_pos, path = forward_queue.popleft()
            for dr, dc in directions:
                r, c = current_pos[0] + dr, current_pos[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in forward_visited:
                    if (r, c) in backward_visited:
                        return path + [(r, c)]
                    forward_visited.add((r, c))
                    forward_queue.append(((r, c), path + [(r, c)]))

        # Expand backward direction
        if backward_queue:
            current_pos, path = backward_queue.popleft()
            for dr, dc in directions:
                r, c = current_pos[0] + dr, current_pos[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in backward_visited:
                    if (r, c) in forward_visited:
                        return path + [(r, c)]
                    backward_visited.add((r, c))
                    backward_queue.append(((r, c), path + [(r, c)]))

    return []  # No path found
