import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def manhattan_distance(pos, goal):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    # Priority queue: (f, g, pos, path)
    pq = [(manhattan_distance(start, goal), 0, start, [start])]
    visited = set()

    while pq:
        f, g, current, path = heapq.heappop(pq)
        if current == goal:
            return path
        if current in visited:
            continue
        visited.add(current)
        r, c = current
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                new_g = g + 1
                new_f = new_g + manhattan_distance((nr, nc), goal)
                heapq.heappush(pq, (new_f, new_g, (nr, nc), path + [(nr, nc)]))

    return []
