from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = deque([start])
    visited.add(start)
    came_from = {}

    found = False
    while queue:
        current = queue.popleft()
        if current == goal:
            found = True
            break
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < rows and 0 <= c < cols:
                if grid[r][c] == '.' and (r, c) not in visited:
                    visited.add((r, c))
                    queue.append((r, c))
                    came_from[(r, c)] = current

    if not found:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from.get(current)
        if current is None:
            break
    path.append(start)
    path.reverse()
    return path
