    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm to find the shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

