        _, current, cost, path = heapq.heappop(pq)

        if current == t:
            return cost

        if current in visited:
            continue

        visited.add(current)

        for neighbor, weight in graph[current]:
            if neighbor not in visited:
                new_cost = cost + weight
                heapq.heappush(pq, (new_cost + heuristic(neighbor, t), neighbor, new_cost, path + [neighbor]))

    return -1
