import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bidirectional Dijkstra's algorithm
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        pq = [(0, start)]
        prev = [-1] * n

        while pq:
            current_dist, u = heapq.heappop(pq)
            if u == end:
                break
            if current_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heapq.heappush(pq, (dist[v], v))
        return dist, prev

    # Run Dijkstra from s and t
    dist_s, _ = dijkstra(s, t)
    dist_t, _ = dijkstra(t, s)

    # Check if t is reachable from s
    if dist_s[t] == float('inf'):
        return -1

    # Bidirectional search: meet in the middle
    dist_start = [float('inf')] * n
    dist_start[s] = 0
    pq_start = [(0, s)]
    visited_start = [False] * n

    dist_end = [float('inf')] * n
    dist_end[t] = 0
    pq_end = [(0, t)]
    visited_end = [False] * n

    while pq_start and pq_end:
        # Expand from start
        while pq_start:
            d, u = heapq.heappop(pq_start)
            if visited_start[u]:
                continue
            visited_start[u] = True
            if u == t:
                return d
            for v, w in adj[u]:
                if not visited_start[v] and dist_start[v] > d + w:
                    dist_start[v] = d + w
                    heapq.heappush(pq_start, (dist_start[v], v))

        # Expand from end
        while pq_end:
            d, u = heapq.heappop(pq_end)
            if visited_end[u]:
                continue
            visited_end[u] = True
            if u == s:
                return d
            for v, w in adj[u]:
                if not visited_end[v] and dist_end[v] > d + w:
                    dist_end[v] = d + w
                    heapq.heappush(pq_end, (dist_end[v], v))

    return -1
