def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bidirectional Dijkstra's algorithm
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [-1] * n
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                break
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        return dist, prev

    # Run Dijkstra from both ends
    dist_s, _ = dijkstra(s, t)
    dist_t, _ = dijkstra(t, s)

    # Find the shortest path using meet-in-the-middle
    # Now run Dijkstra from both ends and find meeting point
    dist_s, prev_s = dijkstra(s, t)
    dist_t, prev_t = dijkstra(t, s)

    # Try to find the meeting point
    visited_s = set()
    visited_t = set()
    queue_s = [(s, 0)]
    queue_t = [(t, 0)]
    found = False
    result = -1

    while queue_s and queue_t:
        u, d_s = queue_s.pop(0)
        if u in visited_s:
            continue
        visited_s.add(u)
        for v, w in graph[u]:
            if v not in visited_s:
                queue_s.append((v, d_s + w))
            if v in visited_t:
                result = d_s + w + dist_t[v]
                found = True
                break
        if found:
            break

        v, d_t = queue_t.pop(0)
        if v in visited_t:
            continue
        visited_t.add(v)
        for u, w in graph:
            if u == v:
                for w2, _ in graph[u]:
                    u2 = w2
                    if u2 not in visited_t:
                        queue_t.append((u2, d_t + w2))
                    if u2 in visited_s:
                        result = d_t + w2 + dist_s[u2]
                        found = True
                        break
        if found:
            break

    if found:
        return result
    else:
        return -1
