def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm with a priority queue
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == end:
                return current_dist
            if current_dist > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Bidirectional Dijkstra's algorithm
    dist_from_s = [float('inf')] * n
    dist_from_t = [float('inf')] * n
    pq_s = [(0, s)]
    pq_t = [(0, t)]
    dist_from_s[s] = 0
    dist_from_t[t] = 0

    while pq_s and pq_t:
        # Expand from s
        d_s, u = heapq.heappop(pq_s)
        if d_s > dist_from_s[u]:
            continue
        for v, w in graph[u]:
            if dist_from_s[v] > d_s + w:
                dist_from_s[v] = d_s + w
                heapq.heappush(pq_s, (dist_from_s[v], v))

        # Expand from t
        d_t, u = heapq.heappop(pq_t)
        if d_t > dist_from_t[u]:
            continue
        for v, w in graph[u]:
            if dist_from_t[v] > d_t + w:
                dist_from_t[v] = d_t + w
                heapq.heappush(pq_t, (dist_from_t[v], v))

        # Check for meeting point
        if dist_from_s[t] < float('inf') or dist_from_t[s] < float('inf'):
            break

    # Calculate the shortest path using the bidirectional results
    min_dist = float('inf')
    for i in range(n):
        if dist_from_s[i] + dist_from_t[i] < min_dist:
            min_dist = dist_from_s[i] + dist_from_t[i]

    return min_dist if min_dist < float('inf') else -1
