    if s == t:
        return 0

    # Initialize distance matrix
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    # Set the distance to self to 0
    for i in range(n):
        dist[i][i] = 0

    # Populate the distance matrix with given edges
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

