                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # Check if there's a path from s to t
    if dist[s][t] == INF:
        return -1
    else:
        return dist[s][t]
